SELECT count(*) lines, count(*) FILTER(WHERE w.recipe_id>0) positive_recipe_id, count(d.recipe_id) matched_current_definition, count(*) FILTER(WHERE w.recipe_id>0 AND d.recipe_id IS NULL) missing_definition FROM canonical_wastage w LEFT JOIN canonical_recipe_definition d ON d.source_system=w.source_system AND d.recipe_id=w.recipe_id AND d.superseded_at IS NULL WHERE w.superseded_at IS NULL;
SELECT count(*) names, count(*) FILTER(WHERE group_name='Food') food_parent, count(*) FILTER(WHERE description IS NULL OR btrim(description)='') blank_definitions FROM product_category;
SELECT count(*) FILTER(WHERE a.status='NEEDS_REVIEW') review_rows, sum(abs(s.amount)) FILTER(WHERE a.status='NEEDS_REVIEW') review_abs_amount, sum(abs(s.amount)) FILTER(WHERE c.name='Beer') beer_abs_amount, count(*) FILTER(WHERE a.product_name_key IS NULL) unmatched_rows FROM resolved_product_sales s LEFT JOIN product_category_assignment a USING(product_name_key) LEFT JOIN product_category c ON c.id=a.product_category_id WHERE s.trading_date BETWEEN '2026-10-26' AND '2026-11-01';
SELECT source_system,count(*) alias_keys_with_multiple_ids FROM (SELECT source_system,product_name_key FROM canonical_product_sales WHERE superseded_at IS NULL AND source_product_ref IS NOT NULL GROUP BY source_system,product_name_key HAVING count(DISTINCT source_product_ref)>1) t GROUP BY 1;
SELECT count(*) total,count(*) FILTER(WHERE amount IS NULL) unresolved FROM resolved_product_sales WHERE trading_date BETWEEN '2026-10-26' AND '2026-11-01';
